(sh) => { f(sh);
    sh.vertexShader = 'varying vec3 vLp;\n' + sh.vertexShader.replace('#include <begin_vertex>', '#include <begin_vertex>\n  vLp = position;');
    sh.fragmentShader = `varying vec3 vLp;
float gH(vec3 p) { return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453); }
float gN(vec3 p) { vec3 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(mix(gH(i), gH(i + vec3(1, 0, 0)), f.x), mix(gH(i + vec3(0, 1, 0)), gH(i + vec3(1, 1, 0)), f.x), f.y), mix(mix(gH(i + vec3(0, 0, 1)), gH(i + vec3(1, 0, 1)), f.x), mix(gH(i + vec3(0, 1, 1)), gH(i + vec3(1, 1, 1)), f.x), f.y), f.z); }
` + sh.fragmentShader.replace('#include <color_fragment>', `#include <color_fragment>
  float gs = fract(dot(diffuseColor.rgb, vec3(12.9, 78.2, 37.7)) * 43.7) * 40.0; vec3 gp = vLp + gs;
  float dirt = (1.0 - smoothstep(0.22, 0.78, vLp.y)) * (0.45 + 0.55 * gN(gp * 3.5)) + smoothstep(0.55, 0.9, gN(vec3(gp.x * 11.0, gp.y * 1.3, gp.z * 11.0))) * 0.35 * (1.0 - smoothstep(0.6, 1.1, vLp.y))
    + smoothstep(1.0, 1.4, vLp.y) * 0.25 * gN(gp * 6.0);
  float rust = smoothstep(0.74, 0.8, gN(gp * 5.0) * 0.7 + gN(gp * 17.0) * 0.3);
  diffuseColor.rgb = mix(diffuseColor.rgb, vec3(0.06, 0.055, 0.045), clamp(dirt, 0.0, 1.0) * 0.6);
  diffuseColor.rgb = mix(diffuseColor.rgb, vec3(0.2, 0.08, 0.035) * (0.6 + 0.4 * gN(gp * 23.0)), rust * 0.6);`)
      .replace('#include <specularmap_fragment>', `#include <specularmap_fragment>
  specularStrength *= 1.0 - clamp(dirt * 0.9 + rust, 0.0, 0.95);`);
  }

